import type { Collection, CollectionId } from '../schema/collections'
import type { SceneMaterial, SceneMaterialId } from '../schema/scene-material'
import type { AnyNode, AnyNodeId } from '../schema/types'

let sceneHistoryPauseDepth = 0
const sceneHistoryPauseLeases = new Set<symbol>()

export type SceneSnapshot = {
  nodes: Record<AnyNodeId, AnyNode>
  rootNodeIds: AnyNodeId[]
  collections: Record<CollectionId, Collection>
  materials: Record<SceneMaterialId, SceneMaterial>
  installedPlugins: string[]
}

export type SceneCommitOrigin = 'local' | 'load' | 'host'

export type SceneCommit = {
  origin: SceneCommitOrigin
  before: SceneSnapshot
  current: SceneSnapshot
  changedNodeIds?: ReadonlySet<AnyNodeId>
}

export type SceneCommitListener = (commit: SceneCommit) => void

type TemporalStoreLike = {
  temporal: {
    getState(): {
      pause(): void
      resume(): void
    }
  }
}

type TemporalHistoryStoreLike<TPastState> = {
  temporal: {
    getState(): {
      pastStates: TPastState[]
    }
    setState(state: { pastStates: TPastState[] }): void
  }
}

const sceneCommitListeners = new Set<SceneCommitListener>()
let sceneCommitTransactionDepth = 0
let pendingSceneCommit: SceneCommit | null = null
const sceneCommitNodeIdScopes: Set<AnyNodeId>[] = []

function mergedNodeIds(
  left: ReadonlySet<AnyNodeId> | undefined,
  right: ReadonlySet<AnyNodeId> | undefined,
) {
  if (!(left || right)) return undefined
  return new Set<AnyNodeId>([...(left ?? []), ...(right ?? [])])
}

export function activeSceneCommitNodeIds(): ReadonlySet<AnyNodeId> | undefined {
  if (sceneCommitNodeIdScopes.length === 0) return undefined
  const ids = new Set<AnyNodeId>()
  for (const scope of sceneCommitNodeIdScopes) {
    for (const id of scope) ids.add(id)
  }
  return ids
}

export function addActiveSceneCommitNodeIds(nodeIds: Iterable<AnyNodeId>): void {
  const scope = sceneCommitNodeIdScopes.at(-1)
  if (!scope) return
  for (const id of nodeIds) scope.add(id)
}

export function runWithSceneCommitNodeIds<TResult>(
  nodeIds: Iterable<AnyNodeId>,
  run: () => TResult,
): TResult {
  const scope = new Set(nodeIds)
  sceneCommitNodeIdScopes.push(scope)
  try {
    return run()
  } finally {
    sceneCommitNodeIdScopes.pop()
    const parentScope = sceneCommitNodeIdScopes.at(-1)
    if (parentScope) {
      for (const id of scope) parentScope.add(id)
    }
  }
}

function areSemanticValuesEqual(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) return true
  if (typeof left !== typeof right || left === null || right === null) return false

  if (Array.isArray(left) || Array.isArray(right)) {
    if (!(Array.isArray(left) && Array.isArray(right)) || left.length !== right.length) return false
    return left.every((value, index) => areSemanticValuesEqual(value, right[index]))
  }

  if (typeof left !== 'object' || typeof right !== 'object') return false

  const leftRecord = left as Record<string, unknown>
  const rightRecord = right as Record<string, unknown>
  const leftKeys = Object.keys(leftRecord)
  const rightKeys = Object.keys(rightRecord)
  if (leftKeys.length !== rightKeys.length) return false

  for (const key of leftKeys) {
    if (!(key in rightRecord) || !areSemanticValuesEqual(leftRecord[key], rightRecord[key])) {
      return false
    }
  }
  return true
}

export function areSceneSnapshotsEqual(left: SceneSnapshot, right: SceneSnapshot): boolean {
  return (
    areSemanticValuesEqual(left.nodes, right.nodes) &&
    areSemanticValuesEqual(left.rootNodeIds, right.rootNodeIds) &&
    areSemanticValuesEqual(left.collections, right.collections) &&
    areSemanticValuesEqual(left.materials, right.materials) &&
    areSemanticValuesEqual(left.installedPlugins, right.installedPlugins)
  )
}

export function subscribeSceneCommits(listener: SceneCommitListener): () => void {
  sceneCommitListeners.add(listener)
  return () => {
    sceneCommitListeners.delete(listener)
  }
}

function emitSceneCommit(commit: SceneCommit): void {
  for (const listener of [...sceneCommitListeners]) {
    try {
      listener(commit)
    } catch (error) {
      console.error('[Scene] Scene commit listener failed', error)
    }
  }
}

export function notifySceneCommit(commit: SceneCommit): void {
  if (areSceneSnapshotsEqual(commit.before, commit.current)) return
  const contextualCommit = {
    ...commit,
    changedNodeIds: mergedNodeIds(commit.changedNodeIds, activeSceneCommitNodeIds()),
  }

  if (sceneCommitTransactionDepth > 0) {
    if (pendingSceneCommit) {
      pendingSceneCommit = {
        origin: pendingSceneCommit.origin,
        before: pendingSceneCommit.before,
        current: contextualCommit.current,
        changedNodeIds: mergedNodeIds(
          pendingSceneCommit.changedNodeIds,
          contextualCommit.changedNodeIds,
        ),
      }
    } else {
      pendingSceneCommit = contextualCommit
    }
    return
  }

  emitSceneCommit(contextualCommit)
}

function beginSceneCommitTransaction(): void {
  sceneCommitTransactionDepth += 1
}

function pendingSceneCommitIsNoOp(): boolean {
  return Boolean(
    pendingSceneCommit &&
      areSceneSnapshotsEqual(pendingSceneCommit.before, pendingSceneCommit.current),
  )
}

function endSceneCommitTransaction(): void {
  if (sceneCommitTransactionDepth === 0) return
  sceneCommitTransactionDepth -= 1
  if (sceneCommitTransactionDepth > 0) return

  const commit = pendingSceneCommit
  pendingSceneCommit = null
  if (commit && !areSceneSnapshotsEqual(commit.before, commit.current)) {
    emitSceneCommit(commit)
  }
}

export function pauseSceneHistory(sceneStore: TemporalStoreLike): void {
  if (getSceneHistoryPauseDepth() === 0) {
    sceneStore.temporal.getState().pause()
  }
  sceneHistoryPauseDepth += 1
}

export function resumeSceneHistory(sceneStore: TemporalStoreLike): void {
  if (sceneHistoryPauseDepth === 0) {
    return
  }

  sceneHistoryPauseDepth -= 1
  if (getSceneHistoryPauseDepth() === 0) {
    sceneStore.temporal.getState().resume()
  }
}

export function acquireSceneHistoryPause(sceneStore: TemporalStoreLike): () => void {
  if (getSceneHistoryPauseDepth() === 0) {
    sceneStore.temporal.getState().pause()
  }
  const lease = Symbol('scene-history-pause')
  sceneHistoryPauseLeases.add(lease)
  let released = false
  return () => {
    if (released) return
    released = true
    sceneHistoryPauseLeases.delete(lease)
    if (getSceneHistoryPauseDepth() === 0) {
      sceneStore.temporal.getState().resume()
    }
  }
}

export function getSceneHistoryPauseDepth(): number {
  return sceneHistoryPauseDepth + sceneHistoryPauseLeases.size
}

export function resetSceneHistoryPauseDepth(): void {
  sceneHistoryPauseDepth = 0
  sceneHistoryPauseLeases.clear()
}

function retainedPastStateCount<TPastState>(before: TPastState[], after: TPastState[]): number {
  for (let start = 0; start < before.length; start += 1) {
    const retained = before.length - start
    if (retained > after.length) continue
    let matches = true
    for (let index = 0; index < retained; index += 1) {
      if (before[start + index] !== after[index]) {
        matches = false
        break
      }
    }
    if (matches) return retained
  }
  return 0
}

export function runAsSingleSceneHistoryStep<TPastState, TResult>(
  sceneStore: TemporalHistoryStoreLike<TPastState>,
  run: () => TResult,
): TResult {
  const beforePastStates = sceneStore.temporal.getState().pastStates
  beginSceneCommitTransaction()
  try {
    const result = run()
    const afterPastStates = sceneStore.temporal.getState().pastStates
    const retainedCount = retainedPastStateCount(beforePastStates, afterPastStates)
    const addedCount = afterPastStates.length - retainedCount

    if (addedCount > 0 && pendingSceneCommitIsNoOp()) {
      sceneStore.temporal.setState({ pastStates: afterPastStates.slice(0, retainedCount) })
    } else if (addedCount > 1) {
      const firstAddedState = afterPastStates[retainedCount]
      if (firstAddedState !== undefined) {
        sceneStore.temporal.setState({
          pastStates: [...afterPastStates.slice(0, retainedCount), firstAddedState],
        })
      }
    }
    return result
  } finally {
    endSceneCommitTransaction()
  }
}

import type { AnyNode, AnyNodeId, WallNode } from '../schema'
import { getAdjacentWallIds } from '../systems/wall/wall-mitering'

export function getHistoryDirtyNodeIds(
  before: Record<string, AnyNode>,
  after: Record<string, AnyNode>,
): Set<AnyNodeId> {
  const dirty = new Set<AnyNodeId>()
  const changedWalls = new Set<string>()
  const changedHosts = new Set<string>()
  const add = (id: string | null | undefined) => {
    if (id && after[id]) dirty.add(id as AnyNodeId)
  }

  const visitChange = (id: string) => {
    const previous = before[id]
    const next = after[id]
    if (previous === next) return
    add(id)
    add(previous?.parentId)
    add(next?.parentId)

    if (previous?.type === 'wall' || next?.type === 'wall') {
      changedWalls.add(id)
      if (
        previous?.type !== 'wall' ||
        next?.type !== 'wall' ||
        previous.thickness !== next.thickness ||
        previous.height !== next.height ||
        previous.curveOffset !== next.curveOffset
      ) {
        changedHosts.add(id)
      }
    }

    if (previous && !next && previous.parentId) {
      const parent = after[previous.parentId]
      // Preserve deletion's sibling refresh for merged geometry consumers.
      if (parent && 'children' in parent && Array.isArray(parent.children)) {
        for (const childId of parent.children) add(childId)
      }
    }
  }

  for (const id in before) visitChange(id)
  for (const id in after) {
    if (!before[id]) visitChange(id)
  }

  if (changedWalls.size === 0) return dirty

  for (const nodes of [before, after]) {
    const wallsByLevel = new Map<string | null, WallNode[]>()
    for (const id of changedWalls) {
      const wall = nodes[id]
      if (wall?.type === 'wall' && !wallsByLevel.has(wall.parentId)) {
        wallsByLevel.set(wall.parentId, [])
      }
    }
    for (const id in nodes) {
      const node = nodes[id]!
      if (node.type === 'wall') {
        wallsByLevel.get(node.parentId)?.push(node)
      }
      if (
        node.parentId &&
        changedHosts.has(node.parentId) &&
        (node.type === 'door' || node.type === 'window' || node.type === 'item')
      ) {
        add(node.id)
      }
    }
    // Former junctions must rebuild too; the viewer only sees the restored layout.
    for (const walls of wallsByLevel.values()) {
      const changed = new Set(walls.filter((wall) => changedWalls.has(wall.id)).map((w) => w.id))
      for (const id of getAdjacentWallIds(walls, changed)) add(id)
    }
  }
  return dirty
}

#!/usr/bin/env python3
"""Freshness and migration contracts for native, desktop, and 3D stacks."""

import csv
import sys
import unittest
from pathlib import Path
from urllib.parse import urlsplit

SCRIPTS_DIR = Path(__file__).resolve().parents[1]
if str(SCRIPTS_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPTS_DIR))

from core import (DATA_DIR, STACK_CONFIG, STACK_CURRENT_APPLICABILITY,
                  search_stack)  # noqa: E402
from validate_data import STACK_OFFICIAL_HOSTS  # noqa: E402

STACKS = {
    "react-native", "flutter", "swiftui", "jetpack-compose", "avalonia",
    "uwp", "winui", "wpf", "uno", "javafx", "threejs", "laravel",
}


def _rows(stack):
    path = DATA_DIR / STACK_CONFIG[stack]["file"]
    with path.open(encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


class TestNativeDesktopStackFreshness(unittest.TestCase):
    def test_rows_have_final_freshness_metadata(self):
        for stack in STACKS:
            for row in _rows(stack):
                with self.subTest(stack=stack, row=row["No"]):
                    expected = "deprecated" if stack == "uwp" else "active"
                    self.assertEqual(row["Status"], expected)
                    self.assertTrue(row["Applies To"].startswith(
                        STACK_CURRENT_APPLICABILITY[stack]))
                    self.assertRegex(row["Verified At"], r"^\d{4}-\d{2}-\d{2}$")
                    self.assertEqual("legacy" in row["Applies To"], stack == "uwp")

    def test_high_impact_rows_use_official_sources(self):
        for stack in STACKS:
            for row in _rows(stack):
                if row["Severity"] not in {"Critical", "High"}:
                    continue
                with self.subTest(stack=stack, row=row["No"]):
                    parsed = urlsplit(row["Docs URL"])
                    self.assertEqual(parsed.scheme, "https")
                    self.assertIn(parsed.hostname, STACK_OFFICIAL_HOSTS[stack])

    def test_current_mobile_contracts(self):
        cases = {
            ("react-native", "Hermes bundled default engine"): "hermes",
            ("flutter", "predictive back result callback"): "onpopinvokedwithresult",
            ("flutter", "accessible nonlinear text scaling"): "textscaler",
            ("swiftui", "multicolumn navigation sidebar detail"): "navigationsplitview",
        }
        for (stack, query), expected in cases.items():
            with self.subTest(stack=stack):
                result = search_stack(query, stack, max_results=1)
                self.assertEqual(result["count"], 1)
                recommended = " ".join(
                    result["results"][0][field]
                    for field in ("Guideline", "Do", "Code Good")
                ).casefold()
                self.assertIn(expected, recommended)

    def test_windows_current_and_maintenance_lanes_are_visible(self):
        current = search_stack("new Windows desktop app Windows App SDK", "winui")
        legacy = search_stack("UWP maintenance x:Bind migration", "uwp")
        self.assertGreater(current["count"], 0)
        self.assertGreater(legacy["count"], 0)
        self.assertEqual({row["Status"] for row in current["results"]}, {"active"})
        self.assertEqual({row["Status"] for row in legacy["results"]}, {"deprecated"})
        self.assertTrue(any("winui" in " ".join(row.values()).casefold()
                            for row in legacy["results"]))
        successor = search_stack(
            "which Windows UI framework should a brand new app choose instead of legacy UWP",
            "uwp", max_results=1,
        )
        self.assertEqual("Prefer WinUI 3 for new projects", successor["results"][0]["Guideline"])

    def test_old_version_without_curated_rows_abstains(self):
        cases = {
            "react-native": "React Native 0.75 Hermes",
            "flutter": "Flutter SDK 3.22 back navigation",
            "swiftui": "iOS 15 SwiftUI navigation",
            "avalonia": "Avalonia UI v11 storage picker",
            "winui": "WinUI SDK 2 desktop app",
            "javafx": "JavaFX SDK 21 table view",
            "threejs": "Three.js r128 OrbitControls",
            "laravel": "Laravel 12 validation",
        }
        for stack, query in cases.items():
            with self.subTest(stack=stack):
                self.assertEqual(search_stack(query, stack)["count"], 0)

    def test_migration_intent_returns_current_replacements(self):
        cases = {
            "flutter": "replace deprecated WillPopScope with current Flutter API",
            "react-native": "upgrade legacy Hermes configuration",
            "threejs": "replace deprecated outputEncoding with current color space",
        }
        for stack, query in cases.items():
            with self.subTest(stack=stack):
                result = search_stack(query, stack)
                self.assertGreater(result["count"], 0)
                self.assertEqual({row["Status"] for row in result["results"]}, {"active"})

        versioned_cases = {
            "react-native": "upgrade React Native 0.75 to React Native 0.86 Hermes",
            "flutter": "upgrade Flutter 3.22 to Flutter 3.44 predictive back",
            "threejs": "upgrade Three.js r128 to r185 outputColorSpace",
        }
        for stack, query in versioned_cases.items():
            with self.subTest(stack=stack, query=query):
                result = search_stack(query, stack)
                self.assertGreater(result["count"], 0)
                self.assertEqual({row["Status"] for row in result["results"]}, {"active"})

    def test_standalone_current_and_deprecated_identifiers_resolve_replacement(self):
        cases = {
            ("flutter", "onPopInvokedWithResult"): "PopScope",
            ("flutter", "TextScaler"): "large fonts",
            ("threejs", "outputColorSpace"): "Color Space",
            ("threejs", "outputEncoding"): "Color Space",
        }
        for (stack, query), guideline in cases.items():
            with self.subTest(stack=stack, query=query):
                result = search_stack(query, stack, max_results=1)
                self.assertEqual(result["count"], 1)
                self.assertIn(guideline.casefold(), result["results"][0]["Guideline"].casefold())

    def test_current_threejs_uses_supported_module_and_color_apis(self):
        cases = {
            "Three.js current OrbitControls addon import": "three/addons/",
            "Three.js current renderer color space": "outputcolorspace",
        }
        for query, expected in cases.items():
            with self.subTest(query=query):
                result = search_stack(query, "threejs", max_results=1)
                self.assertEqual(result["count"], 1)
                recommended = " ".join(
                    result["results"][0][field]
                    for field in ("Guideline", "Do", "Code Good")
                ).casefold()
                self.assertIn(expected, recommended)

    def test_deprecated_symbols_are_not_recommended_by_current_rows(self):
        forbidden = {
            "react-native": ("hermes_enabled",),
            "flutter": ("willpopscope", "onpopinvoked:", "textscalefactor"),
            "swiftui": ("navigationview", "presentationmode"),
            "winui": ("dispatcher.runasync", "system.windows"),
            "uno": ("system.windows", 'requestedtheme="default"'),
            "javafx": ("fxpermission", "javadoc/21"),
            "threejs": (
                "r128", "three.orbitcontrols", "outputencoding",
                "three.srgbencoding", "examples/js/controls",
            ),
        }
        for stack, tokens in forbidden.items():
            for row in _rows(stack):
                if row["Status"] != "active":
                    continue
                recommended = " ".join(
                    row[field] for field in ("Guideline", "Do", "Code Good")
                ).casefold()
                for token in tokens:
                    with self.subTest(stack=stack, row=row["No"], token=token):
                        self.assertNotIn(token, recommended)


if __name__ == "__main__":
    unittest.main()

#!/usr/bin/env python3
"""Freshness and generation-isolation contracts for web stack guidance."""

import csv
import sys
import unittest
from pathlib import Path
from urllib.parse import urlsplit

SCRIPTS_DIR = Path(__file__).resolve().parents[1]
if str(SCRIPTS_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPTS_DIR))

from core import DATA_DIR, STACK_CONFIG, WEB_STACKS, search_stack  # noqa: E402
from validate_data import STACK_OFFICIAL_HOSTS  # noqa: E402

CURRENT_APPLICABILITY = {
    "react": "react 19.2.x",
    "nextjs": "nextjs 16.2",
    "vue": "vue 3.5.x",
    "svelte": "svelte 5",
    "astro": "astro 7.1.6",
    "angular": "angular 22.x",
    "html-tailwind": "html-tailwind 4.3",
    "shadcn": "shadcn cli 4",
    "nuxtjs": "nuxtjs 4.5",
    "nuxt-ui": "nuxt-ui 4.10",
}


def _rows(stack):
    path = DATA_DIR / STACK_CONFIG[stack]["file"]
    with path.open(encoding="utf-8", newline="") as handle:
        return list(csv.DictReader(handle))


class TestWebStackFreshness(unittest.TestCase):
    def test_web_rows_have_explicit_freshness_metadata(self):
        for stack in WEB_STACKS:
            for row in _rows(stack):
                with self.subTest(stack=stack, row=row["No"]):
                    self.assertIn(row["Status"], {"active", "deprecated"})
                    self.assertTrue(row["Applies To"].startswith(stack))
                    self.assertRegex(row["Verified At"], r"^\d{4}-\d{2}-\d{2}$")
                    self.assertEqual(
                        "legacy" in row["Applies To"].casefold(),
                        row["Status"] == "deprecated",
                    )

    def test_high_impact_rows_use_official_sources(self):
        for stack in WEB_STACKS:
            for row in _rows(stack):
                if row["Severity"] not in {"Critical", "High"}:
                    continue
                with self.subTest(stack=stack, row=row["No"]):
                    parsed = urlsplit(row["Docs URL"])
                    self.assertEqual(parsed.scheme, "https")
                    self.assertIn(parsed.hostname, STACK_OFFICIAL_HOSTS[stack])

    def test_active_rows_use_the_verified_current_applicability(self):
        for stack, applicability in CURRENT_APPLICABILITY.items():
            for row in _rows(stack):
                if row["Status"] != "active":
                    continue
                with self.subTest(stack=stack, row=row["No"]):
                    self.assertTrue(row["Applies To"].startswith(applicability))

    def test_svelte_current_and_legacy_queries_do_not_mix_generations(self):
        current = search_stack("Svelte state props and events", "svelte")
        legacy = search_stack("Svelte 4 legacy props and events", "svelte")
        self.assertGreater(current["count"], 0)
        self.assertGreater(legacy["count"], 0)
        self.assertEqual({row["Status"] for row in current["results"]}, {"active"})
        self.assertEqual({row["Status"] for row in legacy["results"]}, {"deprecated"})
        self.assertTrue(all("legacy" in row["Applies To"] for row in legacy["results"]))

    def test_explicit_old_major_uses_only_curated_legacy_rows(self):
        cases = {
            "nextjs": "Next.js 15 middleware auth matcher",
            "html-tailwind": "Tailwind 3 JIT content configuration",
            "nuxtjs": "Nuxt 3 app config runtime config migration",
        }
        for stack, query in cases.items():
            with self.subTest(stack=stack):
                result = search_stack(query, stack)
                self.assertGreater(result["count"], 0)
                self.assertEqual(
                    {row["Status"] for row in result["results"]}, {"deprecated"}
                )

    def test_current_major_migration_query_stays_on_current_guidance(self):
        result = search_stack("Next.js 16 migration to proxy", "nextjs")
        self.assertGreater(result["count"], 0)
        self.assertEqual({row["Status"] for row in result["results"]}, {"active"})

    def test_shadcn_named_base_excludes_incompatible_composition_apis(self):
        result = search_stack("shadcn Base UI asChild composition", "shadcn")
        self.assertGreater(result["count"], 0)
        self.assertEqual(result["results"][0]["Guideline"],
                         "Use render for Base UI composition")
        self.assertTrue(all("base=radix" not in row["Applies To"]
                            for row in result["results"]))

    def test_common_old_major_syntaxes_select_legacy_guidance(self):
        cases = {
            "svelte": "svelte@4 props events",
            "nextjs": "Next.js (v15) middleware",
            "html-tailwind": "tailwindcss@3 JIT",
            "nuxtjs": "nuxt@3 app config",
        }
        for stack, query in cases.items():
            with self.subTest(stack=stack, query=query):
                result = search_stack(query, stack)
                self.assertGreater(result["count"], 0)
                self.assertEqual(
                    {row["Status"] for row in result["results"]}, {"deprecated"}
                )

    def test_old_major_without_curated_legacy_guidance_abstains(self):
        result = search_stack("Astro 5 content collections", "astro")
        self.assertEqual(result["count"], 0)
        self.assertEqual(result["results"], [])

    def test_current_high_drift_queries_return_current_contracts(self):
        cases = {
            ("nextjs", "Next.js 16 request interception proxy"): "proxy",
            ("html-tailwind", "Tailwind 4 CSS-first source detection"): "source",
            ("react", "React Effect Event latest values inside an Effect"): "effect event",
        }
        for (stack, query), expected in cases.items():
            with self.subTest(stack=stack):
                result = search_stack(query, stack, max_results=1)
                self.assertEqual(result["count"], 1)
                row = result["results"][0]
                self.assertEqual(row["Status"], "active")
                self.assertIn(expected, row["Guideline"].casefold())

    def test_stack_without_curated_legacy_rows_keeps_nonlegacy_fallback(self):
        result = search_stack(
            "which Windows UI framework should a new app choose instead of legacy UWP",
            "uwp",
        )
        self.assertGreater(result["count"], 0)

    def test_stale_apis_are_not_recommended_by_active_rows(self):
        forbidden = {
            "svelte": ("$: ", "export let ", "on:click", "createeventdispatcher"),
            "nextjs": ("middleware.ts", "function middleware", "skipmiddleware"),
            "html-tailwind": (
                "content: [", "mode: 'jit'", "@tailwindcss/aspect-ratio",
                "tailwindcss-container-queries",
            ),
            "nuxt-ui": ("#cell-status", "sortable: true", "v-model:content"),
            "astro": (
                "output: 'hybrid'", "viewtransitions", "@astrojs/tailwind",
                "astro add prefetch",
            ),
        }
        for stack, tokens in forbidden.items():
            for row in _rows(stack):
                if row["Status"] != "active":
                    continue
                recommended = " ".join(
                    row[field] for field in ("Guideline", "Do", "Code Good")
