const createCursorManager = (maxEntries = 100) => {
  let history = []
  let idx = -1

  const isSame = (c1, c2) => {
    if (!c1 || !c2 || c1.id !== c2.id) return false
    const isSameStart = c1.start !== undefined && c1.start === c2.start
    const isSamePos = c1.pos?.line === c2.pos?.line && c1.pos?.ch === c2.pos?.ch
    return isSameStart || isSamePos
  }

  return {
    get history() {
      return history
    },
    get currentIndex() {
      return idx
    },
    get currentCursor() {
      return (history.length <= 0 || idx === -1) ? null : history[idx]
    },
    push: (cursor) => {
      if (history.length > 0 && isSame(cursor, history[idx])) return

      // If the current pointer is not at the end of the history record,
      // it indicates that the user has performed a "back" operation.
      // At this time, adding a new record requires removing subsequent history records
      if (idx < history.length - 1) {
        history = history.slice(0, idx + 1)
      }
      if (history.length >= maxEntries) {
        history = history.slice(1)
      }

      cursor = cursor.start
        ? { id: cursor.id, type: cursor.type, start: cursor.start }
        : { id: cursor.id, type: "fences-pos", pos: cursor.pos }

      history.push(cursor)
      idx = history.length - 1
    },
    goBack: () => {
      if (history.length <= 0) return null
      if (idx > 0) idx--
      return history[idx]
    },
    goForward: () => {
      if (history.length <= 0) return null
      if (idx < history.length - 1) idx++
      return history[idx]
    },
  }
}

class CursorHistoryPlugin extends BasePlugin {
  cursorManager = createCursorManager(this.config.MAX_HISTORY_ENTRIES)

  hotkey = () => [
    { hotkey: this.config.HOTKEY_GO_FORWARD, callback: this.goForward },
    { hotkey: this.config.HOTKEY_GO_BACK, callback: this.goBack },
  ]

  process = () => {
    $("#write").on("cursorChange", (ev) => {
      const cmd = File.editor.selection.buildUndo()
      if (cmd?.type === "cursor") {
        this.cursorManager.push({ type: cmd.type, id: cmd.id, start: cmd.start, pos: cmd.pos, timeStamp: ev.timeStamp })
      }
    })
  }

  goBack = () => this.jump(this.cursorManager.goBack())
  goForward = () => this.jump(this.cursorManager.goForward())
  jump = (cursor) => {
    if (!cursor) return
    File.editor.undo.exeCommand(cursor)
    this.utils.scrollTo(cursor.id, { focus: false, moveCursor: false, showHiddenEls: false })
  }
}

module.exports = {
  plugin: CursorHistoryPlugin,
}

define([
  'immutable'
], function (Immutable) {
  'use strict';

  function UndoManager(limit, undoScopeHost) {
    this._stack = Immutable.List();
    this._limit = limit;
    this._fireEvent = typeof CustomEvent != 'undefined' && undoScopeHost && undoScopeHost.dispatchEvent;
    this._ush = undoScopeHost;

    this.position = 0;
    this.length = 0;
  }

  UndoManager.prototype.transact = function (transaction, merge) {
    if (arguments.length < 2) {
      throw new TypeError('Not enough arguments to UndoManager.transact.');
    }

    transaction.execute();

    if (this.position > 0) {
      this.clearRedo();
    }

    var transactions;
    if (merge && this.length) {
      transactions = this._stack.first().push(transaction);
      this._stack = this._stack.shift().unshift(transactions);
    }
    else {
      transactions = Immutable.List.of(transaction);
      this._stack = this._stack.unshift(transactions);
      this.length++;

      if (this._limit && this.length > this._limit) {
        this.clearUndo(this._limit);
      }
    }

    this._dispatch('DOMTransaction', transactions);
  };

  UndoManager.prototype.undo = function () {
    if (this.position >= this.length) { return; }

    var transactions = this._stack.get(this.position);
    var i = transactions.size;
    while (i--) {
      transactions.get(i).undo();
    }
    this.position++;

    this._dispatch('undo', transactions);
  };

  UndoManager.prototype.redo = function () {
    if (this.position === 0) { return; }

    this.position--;
    var transactions = this._stack.get(this.position);
    for (var i = 0; i < transactions.size; i++) {
      transactions.get(i).redo();
    }

    this._dispatch('redo', transactions);
  };

  UndoManager.prototype.item = function (index) {
    return index >= 0 && index < this.length ?
      this._stack.get(index).toArray() :
      null;
  };

  UndoManager.prototype.clearUndo = function (position) {
    this._stack = this._stack.take(position !== undefined ? position : this.position);
    this.length = this._stack.size;
  };

  UndoManager.prototype.clearRedo = function () {
    this._stack = this._stack.skip(this.position);
    this.length = this._stack.size;
    this.position = 0;
  };

  UndoManager.prototype._dispatch = function(event, transactions) {
    if (this._fireEvent) {
      this._ush.dispatchEvent(new CustomEvent(event, {
        detail: {transactions: transactions.toArray()},
        bubbles: true,
        cancelable: false
      }));
    }
  }

  return UndoManager;
});

